{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Amoxicillin, a high-transfer analogue, showed 88% absolute oral bioavailability in humans over a 250–1000 mg dose range, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Perindopril, another high-transfer analogue, has an absolute oral bioavailability of about 75% in patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Aminoglutethimide, a lipophilic small-molecule amine, is reported to have near-complete oral bioavailability (≈100%), consistent with high absorption for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Bicifadine, a small-molecule amine, showed approximately 67% absolute oral bioavailability in humans, supporting the high-bioavailability prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Maraviroc, a basic amine with transporter/CYP liabilities, still achieved 33% absolute oral bioavailability at 300 mg in humans, remaining above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "L-theanine, a small polar amino-acid-like molecule, showed at least 72–74% oral bioavailability in humans, supporting high F for small absorbable molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values above the 20% threshold, mostly 33–100%, and the query's small lipophilic primary-amine adamantane structure is consistent with good oral absorption. Therefore, F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself; prediction relies on high-transfer analogues.",
    "Some analogues are structurally distant, but their consistently high measured F values and high transfer scores reduce this concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

